CREATE TABLE users (id BIGINT NOT NULL AUTO_INCREMENT, first_name VARCHAR(80) NOT NULL, last_name VARCHAR(80) NOT NULL, email VARCHAR(190) NOT NULL, phone_number VARCHAR(20) NOT NULL, password_hash VARCHAR(255) NOT NULL, role VARCHAR(30) NOT NULL, status VARCHAR(30) NOT NULL, email_verified BIT NOT NULL DEFAULT 0, phone_verified BIT NOT NULL DEFAULT 0, profile_image VARCHAR(500), last_login_at TIMESTAMP(6) NULL, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY(id), CONSTRAINT uk_users_email UNIQUE(email), CONSTRAINT uk_users_phone_number UNIQUE(phone_number));
CREATE INDEX idx_users_role_status ON users(role,status); CREATE INDEX idx_users_email ON users(email);
CREATE TABLE refresh_tokens (id BIGINT NOT NULL AUTO_INCREMENT, user_id BIGINT NOT NULL, token_hash VARCHAR(128) NOT NULL, expires_at TIMESTAMP(6) NOT NULL, revoked_at TIMESTAMP(6) NULL, replaced_by_token_id BIGINT NULL, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), created_by_ip VARCHAR(64), revoked_by_ip VARCHAR(64), PRIMARY KEY(id), CONSTRAINT fk_refresh_user FOREIGN KEY(user_id) REFERENCES users(id), CONSTRAINT fk_refresh_replaced FOREIGN KEY(replaced_by_token_id) REFERENCES refresh_tokens(id));
CREATE INDEX idx_refresh_user ON refresh_tokens(user_id); CREATE INDEX idx_refresh_hash ON refresh_tokens(token_hash);
CREATE TABLE email_otps (id BIGINT NOT NULL AUTO_INCREMENT, user_id BIGINT NOT NULL, email VARCHAR(190) NOT NULL, purpose VARCHAR(40) NOT NULL, otp_hash VARCHAR(128) NOT NULL, expires_at TIMESTAMP(6) NOT NULL, consumed_at TIMESTAMP(6) NULL, attempt_count INT NOT NULL DEFAULT 0, max_attempts INT NOT NULL, resend_available_at TIMESTAMP(6) NOT NULL, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY(id), CONSTRAINT fk_email_otps_user FOREIGN KEY(user_id) REFERENCES users(id));
CREATE INDEX idx_email_otp_user_purpose ON email_otps(user_id,purpose); CREATE INDEX idx_email_otp_email ON email_otps(email);
CREATE TABLE password_reset_tokens (id BIGINT NOT NULL AUTO_INCREMENT, user_id BIGINT NOT NULL, token_hash VARCHAR(128) NOT NULL, expires_at TIMESTAMP(6) NOT NULL, consumed_at TIMESTAMP(6) NULL, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY(id), CONSTRAINT fk_password_reset_user FOREIGN KEY(user_id) REFERENCES users(id));
CREATE INDEX idx_pwd_reset_hash ON password_reset_tokens(token_hash);
CREATE TABLE social_accounts (id BIGINT NOT NULL AUTO_INCREMENT, user_id BIGINT NOT NULL, provider VARCHAR(30) NOT NULL, provider_user_id VARCHAR(255) NOT NULL, provider_email VARCHAR(190) NOT NULL, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), last_login_at TIMESTAMP(6) NULL, PRIMARY KEY(id), CONSTRAINT uk_social_provider_subject UNIQUE(provider,provider_user_id), CONSTRAINT fk_social_user FOREIGN KEY(user_id) REFERENCES users(id));
CREATE INDEX idx_social_user ON social_accounts(user_id);
